def pack(paragraphs, max_chars):
    out, cur = [], []
    for p in paragraphs:
        if not p.strip():
            continue
        if cur and len('\n\n'.join(cur + [p])) > max_chars:
            out.append('\n\n'.join(cur)); cur = []
        cur.append(p)
    if cur:
        out.append('\n\n'.join(cur))
    return out

def rrf(lists, k=60):
    score = {}
    for lst in lists:
        for rank, d in enumerate(lst, start=1):
            score[d] = score.get(d, 0) + 1 / (k + rank)
    return sorted(score, key=lambda d: (-score[d], d))

def grounded_prompt(question, chunks):
    if not chunks:
        return None
    lines = [f"[{i}] ({c['source']}, p.{c['page']}) {c['text']}" for i, c in enumerate(chunks, 1)]
    return 'Answer only from the sources. Cite as [n]. If they do not contain the answer, reply: Not in the documents.\n<sources>\n' + '\n'.join(lines) + '\n</sources>\n<question>' + question + '</question>'

