import re

def check_answer(answer, n_sources):
    if answer.strip() == 'Not in the documents.':
        return 'refused'
    nums = [int(n) for n in re.findall(r'\[(\d+)\]', answer)]
    if not nums:
        return 'uncited'
    if any(not 1 <= n <= n_sources for n in nums):
        return 'bad citation'
    return 'ok'
